import assert from 'node:assert/strict';
import fs from 'node:fs';
import {PNG} from 'pngjs';
import {DarkRoomContact,getDarkRoomFeet} from '../../../../src/js/environment/DarkRoomContact.js';
import {platforms,phase3Platforms,createBabyState,getEscapeStats} from '../../../../src/js/config.js';
import {OFFICIAL_FRAMES} from '../../../../src/js/assets/officialCharacter.js';
const contact=new DarkRoomContact();
const baseline=JSON.parse(fs.readFileSync('tests/fixtures/active-test-assets/dark-room-physics.json'));
assert.deepEqual({platforms:platforms.map(({contactGroup,...p})=>p),baby:createBabyState(),escape:Array.from({length:12},(_,i)=>getEscapeStats(i,'EASY'))},baseline,'Conserva posições, dimensões, impulsos e dificuldade EASY; só adiciona o grupo de apoio');
assert.equal(platforms[0].contactGroup,platforms[1].contactGroup);
assert.ok(platforms[0].contactGroup);
let checks=0;
for(const phase3 of [false,true])for(const difficulty of ['NORMAL','EASY'])for(const dt of [.5,1,1.2,3])for(const p of phase3?phase3Platforms:platforms){
 const bounds=contact.bounds(p),state={isPhase3:phase3,isEscapeMode:!phase3,gameDifficulty:difficulty};
 for(const edge of ['left','right']){
  const b={...createBabyState(),vx:0,vy:8,onGround:false};
  const f=getDarkRoomFeet(b,state),radius=(f.right-f.left)/2;
  b.x=(edge==='left'?bounds.x-radius+.01:bounds.right+radius-.01)-b.w/2;b.y=bounds.y+1-b.h;
  assert.equal(contact.resolve(b,state,[p],dt)?.index,0,'Parte mínima do sapato permite pouso '+p.style);
  b.vy=-8;assert.equal(contact.resolve(b,state,[p],dt),null,'Subida não cola no apoio');
  b.vy=8;b.y=bounds.y+8*dt+1-b.h;assert.equal(contact.resolve(b,state,[p],dt),null,'Entrada por baixo rejeitada');
  b.y=bounds.y+1-b.h;b.x+=edge==='left'?-.02:.02;assert.equal(contact.resolve(b,state,[p],dt),null,'Transparência não é apoio');checks+=4;
 }
}
const image=PNG.sync.read(fs.readFileSync('assets/art/dark-room/sprites/official-character.png'));
let pixels=0;
for(const pose of ['idle','run','jump','jump_short','high_jump','fall','dash'])for(const frame of OFFICIAL_FRAMES[pose])for(const facing of [-1,1])for(const approach of [false,true]){
 const b={...createBabyState(),facing,onGround:pose==='dash',vx:pose==='dash'?3:2};
 const state={isEscapeMode:!approach,isPhase3:false},feet=getDarkRoomFeet(b,state),center=b.x+b.w/2;
 // O dash só aparece na fuga; no início o renderizador escolhe corrida.
 if(approach&&pose==='dash')continue;
 const scale=(b.h/50+1/frame.h)*(approach?1.08:1);
 for(let y=frame.h-9;y<frame.h;y++)for(let x=0;x<frame.w;x++)if(image.data[((frame.y+y)*image.width+frame.x+x)*4+3]>=96){
  const world=center+(x-frame.anchorX)*scale*facing;
  assert.ok(world>=feet.left&&world<=feet.right,'Todo pixel do sapato está no apoio: '+pose);pixels++;
 }
}
console.log(JSON.stringify({resultado:'aprovado',checks,pixelsDosSapatos:pixels,plataformas:platforms.length+phase3Platforms.length}));
